/**
 * Generate Wave 2G curated statute + court-rule deepen bundles from official/public sources.
 * Deterministic snapshots — no CourtListener, no Lexis/Westlaw.
 */
"use strict";

const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const outDir = path.join(root, "packages/research/corpus/bundles");
const retrievedAt = "2026-09-18T16:00:00.000Z";

function auth(p) {
  return {
    title: p.title,
    shortTitle: p.shortTitle || p.citation,
    authorityType: p.authorityType || "statute",
    jurisdiction: p.jurisdiction,
    authorityState: p.authorityState,
    citation: p.citation,
    normalizedCitation: p.normalizedCitation || p.citation,
    sourceProvider: "us-primary-corpus",
    sourceExternalId: p.sourceExternalId,
    canonicalSourceUrl: p.canonicalSourceUrl,
    hierarchyPath: p.hierarchyPath || [
      { level: "code", ref: p.authorityState, label: p.codeLabel || "Code" },
      { level: "section", ref: p.sectionRef, label: p.shortTitle || p.citation },
    ],
    bundleSourceClass: "PRIMARY_OFFICIAL",
    bundlePracticeAreas: p.practiceAreas || ["civil"],
    content: p.content,
    sections: p.sections || [{ sectionRef: p.sectionRef, content: p.sectionSummary }],
    currentnessStatus: "current_as_of_source_date",
    sourceMetadata: {
      retrievalMethod: "official_codification_snapshot",
      retrievedAt,
      statuteTopic: p.statuteTopic,
      sourceOwner: p.sourceOwner,
      wave: "2G",
    },
  };
}

